cssCode:
.fold-wrap { height: 250vh; width: 100%; background: #000; position: relative; }
.fold-sticky {
  position: sticky; top: 0; height: 100vh; width: 100%;
  display: flex; align-items: center; justify-content: center;
  perspective: 1500px; overflow: hidden; background: #050505;
}
.fold-door {
  position: absolute; width: 50vw; height: 100vh; background: #111;
  border: 2px solid #333; z-index: 10;
  transition: transform 0.1s linear;
}
.fold-left { left: 0; transform-origin: left center; border-right: 2px solid #00ffcc; box-shadow: inset -20px 0 50px rgba(0,0,0,0.8); }
.fold-right { right: 0; transform-origin: right center; border-left: 2px solid #ff007f; box-shadow: inset 20px 0 50px rgba(0,0,0,0.8); }

.fold-content {
  position: absolute; color: white; font-size: 60px; font-weight: 900; font-family: sans-serif;
  text-transform: uppercase; z-index: 1; opacity: 0; transform: scale(0.5);
  transition: opacity 0.1s linear, transform 0.1s linear;
  text-shadow: 0 0 30px #00ffcc, 0 0 60px #ff007f; letter-spacing: 10px;
}

jsCode:
const fC = document.getElementById('container');
fC.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#111;';

fC.innerHTML = `
  <div class="fold-wrap">
    <div class="fold-sticky">
      <div class="fold-door fold-left" id="dLeft"></div>
      <div class="fold-door fold-right" id="dRight"></div>
      <div class="fold-content" id="dContent">ZYNK UNLOCKED</div>
      <div style="position:absolute; bottom:20px; color:#555; z-index:20;">SCROLL TO UNLOCK</div>
    </div>
  </div>
`;

const dLeft = document.getElementById('dLeft');
const dRight = document.getElementById('dRight');
const dContent = document.getElementById('dContent');

fC.addEventListener('scroll', () => {
  const fProg = fC.scrollTop / (fC.scrollHeight - fC.clientHeight);

  // 3D ડોર ઓપનિંગ (Rotate Y)
  const angle = fProg * 110; // 0 થી 110 ડિગ્રી ખુલશે
  dLeft.style.transform = `rotateY(${angle}deg)`;
  dRight.style.transform = `rotateY(${-angle}deg)`;

  // અંદરનું લખાણ ઝૂમ થઈને પ્રકાશિત થશે
  dContent.style.opacity = fProg * 1.5;
  dContent.style.transform = `scale(${0.5 + fProg * 0.5})`;
});
